    },
    {
      "chord_quality": "min7",
      "function_role": "shell-voicing-two-string",
      "narrative": "Heussenstamm prescribes reducing min7 to root, 3rd, and 7th (shell), then dropping the root entirely for compact two-string shapes on the middle strings, to be used alongside a walking bassist. He explicitly warns against mechanically trimming any chord shape to middle strings -- only these specific tones belong there. Chapter 5, p. 48.",
      "source_principle_ids": [],
      "source_work_id": "goldmine-100-jazz-lessons",
      "references": [
