      "granularity_name": "voicing-floor"
    },
    {
      "chord_quality": "dom7",
      "function_role": "lydian-dominant-avoidance-of-natural-4th",
      "narrative": "Heussenstamm prescribes Lydian dominant (Mixolydian with raised 4th) over a natural unaltered dominant seven as an alternative to plain Mixolydian, because the natural 4th clashes with the chordal 3rd when sustained -- Lydian dominant eliminates that clash while accommodating the #11. Chapter 8, p. 93.",
      "source_principle_ids": [],
      "source_work_id": "goldmine-100-jazz-lessons",
      "references": [
        {
          "source": "goldmine-100-jazz-lessons",
