      "provenance": "extracted",
      "granularity_level": "d",
      "granularity_name": "color-tone-policy"
    },
    {
      "chord_quality": "dom7",
      "function_role": "bebop-dominant-scale-charlie-parker",
      "narrative": "Heussenstamm prescribes the bebop dominant scale (Mixolydian plus the natural/major 7th as a passing tone) as a dominant-seven tool favored by Charlie Parker, to be mastered but not overused. Chapter 10, p. 142.",
      "source_principle_ids": [],
      "source_work_id": "goldmine-100-jazz-lessons",
      "references": [
