      "provenance": "extracted",
      "granularity_level": "a",
      "granularity_name": "harmonic-family"
    },
    {
      "chord_quality": "dom7",
      "function_role": "diminished-scale-over-dominant",
      "narrative": "Heussenstamm prescribes the half-step/whole-step diminished scale over dom7 chords -- constructed from the same scale and therefore applicable to the dominant it generates -- and mandates mastery of this sound for all jazz players, paired with a restraint caveat against overuse. The scale covers four keys via three-fret equivalence. Chapter 10, p. 143; Chapter 11, p. 152.",
      "source_principle_ids": [],
      "source_work_id": "goldmine-100-jazz-lessons",
      "references": [
