      "granularity_level": "a",
      "granularity_name": "harmonic-family"
    },
    {
      "chord_quality": "dom7",
      "function_role": "diminished-scale-do-not-overuse",
      "narrative": "Heussenstamm proscribes overuse of the diminished scale over dominant chords: 'All jazz musicians need to get command of this sound... Don't overuse this scale, but you should definitely master it.' The restraint rule is paired with a mastery imperative. Chapter 10, p. 143.",
      "source_principle_ids": [],
      "source_work_id": "goldmine-100-jazz-lessons",
