    },
    {
      "chord_quality": "dom7",
      "function_role": "four-tension-tones-altered-dominant",
      "narrative": "Heussenstamm teaches (attributing to Bob Conti) that exactly four tension tones -- b5, #5, b9, #9 -- distinguish altered dominants from the native dominant scale; all other tones are already present in the dominant key. Mastering application of these four tones is the core altered-dominant task. Chapter 11, p. 145.",
      "source_principle_ids": [],
      "source_work_id": "goldmine-100-jazz-lessons",
      "references": [
