    },
    {
      "chord_quality": "dom7",
      "function_role": "mixolydian-defined-lead-in-tone",
      "narrative": "Heussenstamm prescribes Bb Mixolydian (Bb major scale with b7 instead of natural major 7th) as the starting scale for dominant seven improvisation, and introduces the lead-in tone concept -- a chromatic half-step approach note below the root. Chapter 11, p. 145.",
      "source_principle_ids": [],
      "source_work_id": "goldmine-100-jazz-lessons",
