    },
    {
      "chord_quality": "dom7",
      "function_role": "minor-pentatonic-vs-mixolydian-color-switching",
      "narrative": "Heussenstamm prescribes two contrasting scale choices over a single dominant seventh chord -- minor pentatonic for a bluesy color and Mixolydian for a jazzy color -- and teaches switching between them mid-passage without a chord change, using A7 as the example. Chapter 10, p. 134.",
      "source_principle_ids": [],
      "source_work_id": "goldmine-100-jazz-lessons",
      "references": [
