    },
    {
      "chord_quality": "dom7",
      "function_role": "straight-4-comping-voicing-and-dynamics",
      "narrative": "Heussenstamm prescribes moderate or minimal voicing size (root-3rd-7th small shapes) for straight-4 quarter-note comping in the Freddie Green style, with precise release timing between each chord (not blurred, not too chopped) and low volume -- 'felt more than heard.' Chapter 5, p. 46-47.",
      "source_principle_ids": [],
      "source_work_id": "goldmine-100-jazz-lessons",
      "references": [
